  function setStep(next, opts) {
    const value = Math.max(0, Math.min(TOTAL_STEPS - 1, Number(next) || 0));
    const changed = value !== step;
    step = value;
    render();
    if (changed && opts && opts.scroll) scrollBodyTop();
  }

  function render() {
    tabs.forEach(function (tab, index) {
      const active = index === step;
      tab.classList.toggle('is-active', active);
      tab.setAttribute('aria-selected', active ? 'true' : 'false');
      tab.tabIndex = active ? 0 : -1;
    });
    panes.forEach(function (pane) {
      const active = Number(pane.dataset.stepPane) === step;
      pane.classList.toggle('is-active', active);
      pane.setAttribute('aria-hidden', active ? 'false' : 'true');
      if (active) activePane = pane;
    });
    if (prevBtn) prevBtn.disabled = step === 0;
    if (nextBtn) nextBtn.hidden = step === TOTAL_STEPS - 1;
    if (finishBtn) finishBtn.hidden = step !== TOTAL_STEPS - 1;
    const pct = ((step + 1) / TOTAL_STEPS) * 100;
    if (progressBar) progressBar.style.width = pct + '%';
    if (progressTrack) progressTrack.setAttribute('aria-valuenow', String(Math.round(pct)));
    if (stepLabel) stepLabel.textContent = 'Шаг ' + (step + 1) + ' из ' + TOTAL_STEPS;
    if (stepPercent) stepPercent.textContent = Math.round(pct) + '%';
    if (isOpen) requestAnimationFrame(function(){ centerActiveTab('auto'); });
  }
