function centerActiveTab(behavior) {
  if (!tabsScroller || tabsScroller.scrollWidth <= tabsScroller.clientWidth + 2) return;
  const tab = tabs[step]; if (!tab) return;
  const rect = tab.getBoundingClientRect();
  const containerRect = tabsScroller.getBoundingClientRect();
  const target = tabsScroller.scrollLeft + (rect.left - containerRect.left) + rect.width / 2 - tabsScroller.clientWidth / 2;
  const max = tabsScroller.scrollWidth - tabsScroller.clientWidth;
  tabsScroller.scrollTo({ left: Math.max(0, Math.min(target, max)), behavior: behavior || 'smooth' });
}
